const HOST_ICONS: [RegExp, PlatformIconName][] = [
  [/^(www\.)?(arxiv\.org|alphaxiv\.org)$/, "arxiv"],
  [/^(www\.)?github\.com$/, "github"],
  [/^(www\.)?huggingface\.co$/, "huggingface"],
  [/^(www\.)?(x\.com|twitter\.com)$/, "x"],
  [/^(www\.)?linkedin\.com$/, "linkedin"],
  [/^(www\.)?discord\.(gg|com)$/, "discord"],
  [/^(www\.)?pypi\.org$/, "pypi"],
  [/^(www\.)?nuget\.org$/, "nuget"],
  [/^axo\.axym\.org$/, "docs"],
];

/** Picks the icon for a link target, or undefined when no platform matches. */
export function iconForHref(href: string): PlatformIconName | undefined {
  if (href.startsWith("mailto:")) return "mail";
  if (/^\/work\/[^/]+-demo\/?$/.test(href)) return "demo";
  let host: string;
  try {
    host = new URL(href).hostname;
  } catch {
    return undefined;
  }
  const icon = HOST_ICONS.find(([pattern]) => pattern.test(host))?.[1];
  // A Markdown guide hosted on GitHub is documentation, not the code repository.
  if (icon === "github" && /\/blob\/.*\.md$/.test(href)) return "docs";
  return icon;
}

/** Inline SVG markup, for HTML strings that React does not render (LaTeX pages). */
export function platformIconSvg(name: PlatformIconName, className = "platform-icon"): string {
  const icon = PLATFORM_ICONS[name];
  const paint = icon.kind === "fill"
    ? 'fill="currentColor"'
    : 'fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"';
  const paths = icon.paths.map((d) => `<path d="${d}"/>`).join("");
  return `<svg class="${className}" viewBox="0 0 24 24" width="16" height="16" ${paint} aria-hidden="true" focusable="false">${paths}</svg>`;
}
